// Quartet (CH2, 2H) and triplet (CH3, 3H) of an ethyl group, each drawn about its own centre.
// Lines are Lorentzians of half-width 0.8 Hz; heights follow Pascal's triangle scaled by the H count.
const QUARTET = '0.25/(1+((x+40+1.5J)/0.8)^2) + 0.75/(1+((x+40+0.5J)/0.8)^2) + 0.75/(1+((x+40-0.5J)/0.8)^2) + 0.25/(1+((x+40-1.5J)/0.8)^2)';
const TRIPLET = '0.75/(1+((x-40+J)/0.8)^2) + 1.5/(1+((x-40)/0.8)^2) + 0.75/(1+((x-40-J)/0.8)^2)';

